/**
 * Built using CHelper plug-in
 * Actual solution is at the top
 *
 * @author ks96neko
 */
public class Main {
    public static void main(String[] args) {
        OutputStream outputStream = System.out;
        InputStream inputStream = System.in;
        PrintWriter out = new PrintWriter(outputStream);
        Scanner in = new Scanner(inputStream);
        BAcCepted solver = new BAcCepted();
        solver.solve(1, in, out);
        out.close();
        out.close();
    }

    static class BAcCepted {
        public void solve(int testNumber, Scanner in, PrintWriter out) {
            String r = in.next();
            int rl = r.length();

            String r0 = r.substring(rl - 1, rl);
            String a = "A";

            String shortenedString = r.substring(1, rl - 1);
            int c1mojime = shortenedString.indexOf("C");
            int cNmojime = shortenedString.lastIndexOf("C");

            if (!a.equals(r0)) {
                out.println("WA");
                return;
            }
            if (c1mojime == -1) {
                out.println("WA");
                return;
            }
            if (c1mojime != cNmojime) {
                out.println("WA");
                return;
            }
            for (int i = rl - 2; i > 0; i--) {
                if (r.charAt(i) != 'C' && Character.isUpperCase(r.charAt(i))) {
                    out.println("WA");
                    return;
                }
            }
            out.println("AC");
        }

    }
}

