public class Main {

	public static void main(String[] args) throws IOException {
		BufferedReader br = new BufferedReader(new InputStreamReader(System.in));

		int n = Integer.parseInt(br.readLine());

		int b[] = new int[n];
		int a[] = new int[n + 1];

		String str[] = br.readLine().split(" ");

		for (int i = n; i >= 0; i--) {
			a[i] = Integer.parseInt(str[i]);
		}

		str = br.readLine().split(" ");

		for (int i = 0; i < n; i++) {
			b[i] = Integer.parseInt(str[i]);
		}

		long ans = 0;
		for (int i = n - 1; i >= 0; i--) {
			if (a[i] > 0) {
				ans += Math.min(a[i], b[i]);
				a[i] -= b[i];
				b[i] -= a[i];
			}

			if (a[i] <= 0 && b[i] > 0) {
				ans += Math.min(a[i + 1], b[i]);
				a[i + 1] -= b[i];
				b[i] -= a[i + 1];
			}
		}

		System.out.println(ans);
	}
}

import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.lang.Math.*;
import java.util.*;
import java.math.*;
import java.text.*;
public class Main {
    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        NumberFormat nf = NumberFormat.getInstance();
        nf.setMaximumFractionDigits(8);
        nf.setGroupingUsed(false);
        while(true) {
            int count = Integer.parseInt(br.readLine());
            if(count == 0)break;
            String[] line = br.readLine().split(" ");
            double[] points = new double[count];
            //longの配列に格納
            for(int i=0;i<count;i++) points[i] = Double.parseDouble(line[i]);
            //標準偏差計算
            double sample = 0;
            double ave_d = ave(points);
            double ans = 0;
            for(int i=0;i<points.length;i++)
                sample += (Math.pow((points[i] - ave_d),2));
            ans = Math.sqrt(sample / points.length);
            System.out.println(nf.format(ans));
            if(ans > 0) {
                double[] temp = points.clone();
                Arrays.sort(temp);
                double median = temp[points.length / 2];
                System.out.println(nf.format(median));
            }
        }
    }
    static double sum(double[] tag) {
        double sum = 0;
        for(int i=0;i<tag.length;i++)
            sum += tag[i];
        return sum;
    }
    static double ave(double[] tag) {
        return sum(tag) / tag.length;
    }
    static double median(double[] tag) {
        Arrays.sort(tag);
        return tag[tag.length / 2];
    }
}

