public class Main{
    public static void main(String[] args) {
        Scanner s = new Scanner(System.in);
        int a = s.nextInt();
        int sum = 0;
        for(int k = 0; k < a; k++){
            for(int j = 0; j < a; j++){
                for(int i = 0; i < a; i++){
                    sum = sum + gcd(gcd(k+1,j+1),i+1);
                }
            }
        }
        System.out.println(sum);
    }
    public static int gcd(int a, int b){
        int tmp;
        while ((tmp = a % b) != 0) {
            a = b;
            b = tmp;
        }
        return b;
    }
}

