class Main {
  public static void main(String[] args) {
    Scanner scanner = new Scanner(System.in);

    int N = scanner.nextInt(); //next(文字列), nextDouble, nextLine(1行)とか
    int ans = 0;
    for (int i = N; i >= 1; i--){
      for (int j = N; j >= 1; j--){
        for (int k = N; k >= 1; k--){
          ans += GCD(k, j, i);
        }
      }
    }
    System.out.println(ans);
  }

  public static int GCD(int x, int y, int z) {

    while (x != y){
      if (x > y){
        x = y - (x-y);
      }else{
        y = x - (y-x);
      }
    }

    while (x != z){
      if (x > z){
        x = z - (x-z);
      }else{
        z = x - (z-x);
      }
    }    
    return x;
  }

}

