import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.io.IOException;
import java.util.ArrayList;
public class Main {
	public static void main(String[] args) throws IOException{
		BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
		ArrayList<String> lines = new ArrayList<String>();
		while (br.ready()){
			lines.add(br.readLine());
		}

		int N = Integer.parseInt(lines.get(0));
		String[] tmp = lines.get(1).split(" ");
		int[] num = new int[tmp.length];
		for(int i=0; i<tmp.length; i++){
			num[i] = Integer.parseInt(tmp[i]);
		}
		for(int i=0; i<num.length; i++){
			sort(num, i);
		}
	}

	static void sort(int[] num, int start){
		if(start >= num.length-1) return;
		int key;
		for(int i=start; i<num.length-1; i++){
			key = num[i];
			for(int j=i; j>start && key < num[j-1];j--){
				num[j] = num[j-1];
				num[j-1] = key;
			}
			print(num, start);
		}

	}

	static void print(int[] num, int start){
		for(int i=start; i<num.length-1; i++){
			System.out.print(num[i]);
			System.out.print(" ");
		}
		System.out.println(num[num.length-1]);
	}
}

