public class Main {
    public static void main(String[] args) {
        OutputStream outputStream = System.out;
        InputStream inputStream = System.in;
        OutputWriter out = new OutputWriter(outputStream);
        InputReader in = new InputReader(inputStream);
        BFoodsLovedByEveryone solver = new BFoodsLovedByEveryone();
        solver.solve(1, in, out);
        out.close();
        out.close();
    }

    static class BFoodsLovedByEveryone {
        public void solve(int testNumber, InputReader in, OutputWriter out) {
            int number = in.readInt();
            int[] people = new int[number + 1];
            int m = in.readInt();
            int[] types = new int[m + 1];
            for (int i = 0; i < number; i++) {
                int x = in.readInt();
                for (int j = 0; j < x; j++) {
                    types[in.readInt()]++;
                }
                out.printLine(in.readInt());
            }
            int c = 0;
            for (int i = 1; i <= m; i++) {
                if (types[i] >= number) c++;
            }
            out.printLine(c);
            out.close();
        }

    }

    static class OutputWriter {
        private final PrintWriter writer;

        public OutputWriter(OutputStream outputStream) {
            writer = new PrintWriter(new BufferedWriter(new OutputStreamWriter(outputStream)));
        }

        public OutputWriter(Writer writer) {
            this.writer = new PrintWriter(writer);
        }

        public void close() {
            writer.close();
        }

        public void printLine(int i) {
            writer.println(i);
        }

    }

    static class InputReader {
        private InputStream stream;
        private byte[] buf = new byte[1024];
        private int curChar;
        private int numChars;
        private InputReader.SpaceCharFilter filter;

        public InputReader(InputStream stream) {
            this.stream = stream;
        }

        public int read() {
            if (numChars == -1) {
                throw new InputMismatchException();
            }
            if (curChar >= numChars) {
                curChar = 0;
                try {
                    numChars = stream.read(buf);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
                if (numChars <= 0) {
                    return -1;
                }
            }
            return buf[curChar++];
        }

        public int readInt() {
            int c = read();
            while (isSpaceChar(c)) {
                c = read();
            }
            int sgn = 1;
            if (c == '-') {
                sgn = -1;
                c = read();
            }
            int res = 0;
            do {
                if (c < '0' || c > '9') {
                    throw new InputMismatchException();
                }
                res *= 10;
                res += c - '0';
                c = read();
            } while (!isSpaceChar(c));
            return res * sgn;
        }

        public boolean isSpaceChar(int c) {
            if (filter != null) {
                return filter.isSpaceChar(c);
            }
            return isWhitespace(c);
        }

        public static boolean isWhitespace(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }

        public interface SpaceCharFilter {
            public boolean isSpaceChar(int ch);

        }

    }
}

import java.math.BigInteger;
import java.util.ArrayList;
import java.util.Collections;
import java.util.PriorityQueue;
import java.util.Scanner;

public class Main {

    public static void main(String[] args) {

        Scanner scanner = new Scanner(System.in);

        int N = scanner.nextInt();
        int Hissatu = scanner.nextInt();

        PriorityQueue<BigInteger> monsters = new PriorityQueue<>(Collections.reverseOrder());
        for(int i=0;i<N;i++) {
            monsters.add(scanner.nextBigInteger());
        }

        //except
        if(Hissatu >= N){
            System.out.println(BigInteger.ZERO);
            return;
        }

        ArrayList<BigInteger> queue = new ArrayList<>(monsters);
        for(int i=0;i<Hissatu;i++){
            Collections.reverse(queue);
            queue.remove(0);
        }

        BigInteger answer = BigInteger.ZERO;
        for(BigInteger health : queue){
            answer = answer.add(health);
        }

        System.out.println(answer);
    }
}

