public class Main {
    public static void main (final String[] args) {
        final Scanner sc = new Scanner(System.in);
        long n = sc.nextLong();
        long m = sc.nextLong();

        if (n > m) {
            long temp = n;
            n = m;
            m = temp;
        }

        System.out.println(n*m/gcd(m,n));
