class SelectionSort{
    int[] selSort;
    public SelectionSort(int[] selSort){
        this.selSort = selSort;
    }

    int count = 0;
    public void changeOfSNum(){
        int maxNum = 0;
        int flag = 0;
        for(int i = selSort.length - 1; i >= 0; i--){
            maxNum = selSort[i];
            for(int j = i - 1; j >= 0; j--){
                if(selSort[j] > selSort[i]){
                    selSort[i] = selSort[j];
                    flag = j;
                }
            }
            if(maxNum != selSort[i]){
                selSort[flag] = maxNum;
                count++;
            }
        }
    }

    public void outPutOfSNum(){
        for(int i = 0; i < selSort.length; i++){
            if(i == 0){
                System.out.print(selSort[i]);
                continue;
            }
            System.out.print(" " + selSort[i]);
        }
        System.out.print("\n");
    }

    public void outPutCount(){
        System.out.println(count);
    }
}

