		Scanner sc = new Scanner(System.in);			//文字の入力
		int N = sc.nextInt();
		int ans = 0;
		int numans = 0;

		for(int i = N; i >= 1; i--){
			int sum = counttwo(i);
			ans = Math.max(ans, sum);
			if(sum == ans){
				numans = i;
			}

		}

		for(int i = numans - 1; i > 0; i--){
			int sum = counttwo(i);
			ans = Math.max(ans, sum);
			if(sum == ans){
				numans = i;
			}
		}

		System.out.println(numans);

	}

	static int counttwo(int num){					//2で割れる回数をカウント
		int count = 0;
		while(num % 2 == 0){
			count++;
			num /= 2;

		}
		return count;
	}

}

