        String words1, words2;
        int wordl,result,score1=0,score2=0;
        int n=scan.nextInt();

        for(int i=n-1; i>=0; i--){
            result=0;
            words1=scan.next();
            words2=scan.next();

            wordl=Math.min(words1.length(), words2.length());
