import java.util.ArrayDeque;
import java.util.Deque;
import java.util.Scanner;

public class Main {

    public static String process(TestCase testCase) {
        final String S = testCase.S;

        final char[] chars = S.toCharArray();

        int count = 0;
        Deque<Character> stack = new ArrayDeque<>();
        for (char c : chars) {
            if (stack.isEmpty()) {
                stack.push(c);
                if (stack.size() > 1) {
                    stack.pop();
                    count += 2;
                }
            } else {
                if (stack.peek().equals(c)) {
                    stack.push(c);
                } else {
                    stack.pop();
                    count += 2;
                }
            }
        }

        return String.valueOf(count);
    }

    // Util func

    public static void main(String[] args) {
        TestCase testCase = readFromInput();

        final String result = process(testCase);

        output(result);
    }

    private static TestCase readFromInput() {
        Scanner sc = new Scanner(System.in);

        String S = sc.next();

        return new TestCase(S);
    }

    private static String output(String result) {
        System.out.println(result);
        throw new RuntimeException("Output processed");
    }

    public static class TestCase {
        final String S;

        public TestCase(String S) {
            this.S = S;
        }
    }
}

