			for (int i = azi.size() - 1; i >= 0; i--) {
				answer += azi.get(i);
			}
		} else if (azi.get(azi.size() - 1) < 0) {
			for (int i = azi.size() - 2; i >= 1; i--) {
				answer += azi.get(i);
			}
		} else {
			for (int i = azi.size() - 2; i >= 1; i--) {
				answer += azi.get(i);
			}
		}
		System.out.println(answer);
	}
}

