public class Main {
	public static void main(String[] arg){
		Scanner sc = new Scanner(System.in);
		int a = sc.nextInt();
		int b = sc.nextInt();
		gcd(a,b);
	}

	static void gcd(int n,int m){
		if(m == 1){
			System.out.println(1);
		}else{
			if((n % m) == 0) {
				System.out.println(m);
			}else{
				int m1 = (n % m);
				gcd(m,m1);
			}
		}
		if(a >= b){
			System.out.println(a);
		}
	}
}

