    FastReader in=new FastReader();
    public long pow(long a, long b){
        if(b==0)return 1;
            long ans=pow(a,b/2);
            ans*=ans;
            ans%=mod;
        if(b%2==1){
            ans*=a;
            ans%=mod;
        }
        return ans;
    }

