        int dp[]=new int[n+1];
        for(int i=1;i<n;i++){
            int pre=20000;
            if(i>0){
                pre=dp[i-1]+Math.abs(arr[i]-arr[i-1]);
            }
            int prepre=20000;
            if(i>1){
                prepre=dp[i-2]+Math.abs(arr[i]-arr[i-2]);
            }
            dp[i]=Math.min(pre, prepre);
        }
        out.append(dp[n-1]);
    }
