        public FastReader(String file_name) throws IOException{ 
            din = new DataInputStream(new FileInputStream(file_name)); 
            buffer = new byte[BUFFER_SIZE]; 
            bufferPointer = bytesRead = 0; 
        } 

        public String nextLine() { 
            try{
                byte[] buf = new byte[10000000]; // line length 
                int cnt = 0, c; 
                while ((c = read()) != -1) { 
                    if (c == '\n') 
                        break; 
                    buf[cnt++] = (byte) c; 
                } 
                return new String(buf, 0, cnt); 
            }catch (Exception e){
                System.out.println(e.getMessage());
                return null;
            }
        } 

        public int nextInt()  { 
            int ret = 0; 
            try {
                byte c = read(); 
                while (c <= ' ') 
                    c = read(); 
                boolean neg = (c == '-'); 
                if (neg) c = read(); 
                do{ 
                    ret = ret * 10 + c - '0'; 
                }  while ((c = read()) >= '0' && c <= '9'); 

                if (neg) return -ret; 
                return ret; 
            } catch (Exception e) {
                System.out.println(e.getMessage());
                return -1;
            }
        } 

        public long nextLong()   { 

            try {
                long ret = 0; 
                byte c = read(); 
                while (c <= ' ') c = read(); 
                boolean neg = (c == '-'); 
                if (neg) 
                    c = read(); 
                do { 
                    ret = ret * 10 + c - '0'; 
                } 
                while ((c = read()) >= '0' && c <= '9'); 
                if (neg) 
                    return -ret; 
                return ret;
            } catch (Exception e) {
                System.out.println(e.getMessage());
                return -1;
            }
        } 

        public double nextDouble()  { 

            try {
                double ret = 0, div = 1; 
                byte c = read(); 
                while (c <= ' ') 
                    c = read(); 
                boolean neg = (c == '-'); 
                if (neg) c = read(); 

                do { 
                    ret = ret * 10 + c - '0'; 
                } 
                while ((c = read()) >= '0' && c <= '9'); 
                if (c == '.') { 
                    while ((c = read()) >= '0' && c <= '9') { 
                        ret += (c - '0') / (div *= 10); 
                    } 
                } 

                if (neg) return -ret; 
                return ret;
            } catch (Exception e) {
                System.out.println(e.getMessage());
                return -1;
            }
        } 

        private void fillBuffer() throws IOException{ 
            bytesRead = din.read(buffer, bufferPointer = 0, BUFFER_SIZE); 
            if (bytesRead == -1) 
                buffer[0] = -1; 
        } 

        private byte read() throws IOException  { 
            try{
                if (bufferPointer == bytesRead) 
                    fillBuffer(); 
                return buffer[bufferPointer++]; 
            }catch(Exception e){
                System.out.println(e.getMessage());
                return -1;
            }
        } 

        public void close() throws IOException { 
            if (din == null) 
                return; 
            din.close(); 
        } 
    }

import java.util.ArrayList;
import java.util.Collections;
import java.util.Scanner;

public class Main {

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        ArrayList<Integer> list = new ArrayList<>();
        int n = Integer.parseInt(sc.next());
        int m = Integer.parseInt(sc.next());
        for (int i = m - 1; i >= 0; i--) {
            list.add(Integer.parseInt(sc.next()));
        }
        Collections.sort(list);
        int allVote = 0;
        for (int i = m - 1; i >= 0; i--) {
            allVote += list.get(i);
        }

        double limit = allVote / (4.0 * m);
        String answer = "Yes";
        for (int i = m - 1; i >= 0; i--) {
            int vote = list.get(i);
            if (vote < limit) {
                answer = "No";
                break;
            }
        }
        System.out.println(answer);
        sc.close();
    }

}

