        // 入力
        Scanner sc = new Scanner(System.in);
        int n = Integer.parseInt(sc.next());
        int[] h = new int[n];
        for (int i = n - 1; i >= 0; i--) {
            h[i] = Integer.parseInt(sc.next());
        }

        // 主処理
        boolean judge = true;
        if (1 < n) {
            for (int i = h.length - 2; i >= 0; i--) {
                if (h[i + 0] <= h[i + 1] - 1) {
                    h[i + 1] -= 1;
                } else if (h[i + 0] != h[i + 1]) {
                    judge = false;
                    break;
                }
            }
        }
        String result = judge ? "Yes" : "No";

