public class Main {
    public static void main(String[] args) {
        Scanner cin = new Scanner(System.in);
        int N = cin.nextInt();
        int L = cin.nextInt();
        String[] S = new String[N];
        for (int i = N - 1; i >= 0; i--) {
            S[i] = cin.next().substring(0, L);
        }

        for (int i = 0; i < N - 1; i++) {
            for (int j = i + 1; j < N; j++) {
                if (S[i].compareTo(S[j]) > 0) {
                    String temp = S[i];
                    S[i] = S[j];
                    S[j] = temp;
                }
            }
        }

        StringBuffer sb = new StringBuffer();
        for (int i = 0; i < N; i++) {
            sb.append(S[i]);
        }

        System.out.println(sb.toString());
    }
}

