import java.util.StringTokenizer;

class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        InputReader in = new InputReader(inputStream);
        PrintWriter out = new PrintWriter(outputStream);
        Task solver = new Task();
        solver.solve(in, out);
        out.close();
    }

    static class Task {
    	int ans = Integer.MAX_VALUE;

        void solve(InputReader in, PrintWriter out) {
        	Integer[] menu = {
        		in.nextInt(),
        		in.nextInt(),
        		in.nextInt(),
        		in.nextInt(),
        		in.nextInt()
        	};
        	PatternUtils<Integer> pt = new PatternUtils<>(Arrays.asList(menu));

        	pt.permutation(5).forEach(list -> {
        		int fin = 0;
        		for (Object t : list) {
        			fin += (10 - fin % 10) % 10 + (Integer)t;
        		}
        		ans = Math.min(fin, ans);
        	});

        	out.println(ans);
        }
    }

    static class PatternUtils<E> {
		private int[] indexes;
		private List<E> original;
		private List<Object[]> pattern;

		public PatternUtils(List<E> l) {
			this.original = l;
			this.indexes = new int[original.size()];
			for (int i = 0; i < original.size(); ++i) indexes[i] = i;
		}

		List<Object[]> permutation(int n) {
			pattern = new ArrayList<>();
			search(indexes, new Object[0], n, 0);
			return pattern;
		}

		void search(int[] perm, Object[] items, int rem, int start) {
			if (rem == 0 || perm.length == 0) {
				pattern.add(items);
			} else {
				for (int i = start; i < perm.length; ++i) {
					Object[] nitems = Arrays.copyOfRange(items, 0, items.length + 1);
					nitems[items.length] = original.get(perm[i]);
					search(Arrays.copyOfRange(perm, 0, i).concat(Arrays.copyOfRange(perm, i + 1, perm.length)), nitems, rem - 1, i + 1);
				}
			}
		}
    }

    static class InputReader {
        BufferedReader reader;
        StringTokenizer tokenizer;

        InputReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream));
            tokenizer = null;
        }

        String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    tokenizer = new StringTokenizer(reader.readLine());
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }

        int nextInt() { return Integer.parseInt(next()); }

        long nextLong() { return Long.parseLong(next()); }

        long[] nextLongArray(int n) {
        	long[] arr = new long[n];
        	for (int i = 0; i < n; ++i) {
        		arr[i] = nextLong();
        	}
        	return arr;
        }
    }
}

