                }
                if (inputs[i].equals("-")) {
                    n = op1 - op2;
                }
                if (inputs[i].equals("+")) {
                    n = op1 + op2;
                }
                cursol--;
            }
            else {
                n = Integer.parseInt(inputs[i]);
            }
            operands[cursol++] = n;
        }
        System.out.println(operands[0]);
    }
    static boolean isOperator (String a) {
        if (a.equals("*") || a.equals("-") || a.equals("+")) {
            return true;
        }
        return false;
    }
}

