public class Main {
	public static void main(String[] args) throws Exception {
	    BufferedReader br = new BufferedReader(new InputStreamReader(System.in));

	    int i = 0;
	    while (true) {
		    String[] line = br.readLine().split(" ");

		    int m = Integer.parseInt(line[0]);
		    int f = Integer.parseInt(line[1]);
		    int r = Integer.parseInt(line[2]);

		    if (m == -1 && f == -1 && r == -1) break;

		    if (m == -1 || f == -1) {
		    	System.out.println("F");
		    } else if (80 <= m + f) {
		    	System.out.println("A");
		    } else if (65 <= m + f && m + f < 80) {
		    	System.out.println("B");
		    } else if (50 <= m + f && m + f < 65) {
		    	System.out.println("C");
		    } else if (30 <= m + f && m + f < 50) {
		    	if (50 <= r) {
			    	System.out.println("C");
		    	} else {
			    	System.out.println("D");
		    	}
		    } else 	if (m + f < 30) {
		    	System.out.println("F");
		    }
		    i++;
	    }
	}
}

public class Main {
  static InputReader in;
  static PrintWriter out;

  static class Solution {
    void solve() throws IOException {
      int n = in.nextInt();
      int taropoint = 0;
      int hanakopoint = 0;
      String tarocard;
      String hanakocard;

      for (int i = n - 1; i >= 0; i--) {
        tarocard = in.next();
        hanakocard = in.next();

        if (!tarocard.equals(hanakocard)) {   
            for (int j = hanakocard.length() - 1; j >= 0; j--) {
              if (tarocard.charAt(j) > hanakocard.charAt(j)) {
                taropoint += 3;
                break;
              } else if (tarocard.charAt(j) < hanakocard.charAt(j)){
                hanakopoint += 3;
                break;
              }

              if (j == 0) {
                if (hanakocard.length() == tarocard.length()) {
                  hanakopoint +=3;
                  break;
                } 
                taropoint += 3;
              }
            }
        } else {
          taropoint++;
          hanakopoint++;
        }
      }

      out.println(taropoint + " " + hanakopoint);

//      End solve()
    }

//  End solution
  } 


  public static void main(String[] args) throws IOException {
    in = new InputReader(System.in);
    out = new PrintWriter(System.out);
    Solution solver = new Solution();
    solver.solve();
    out.close();
}

  static class InputReader {
    public BufferedReader br;
    public StringTokenizer st;

    public InputReader(InputStream stream) {
      br = new BufferedReader(new InputStreamReader(stream));
    }

    public int nextInt() throws IOException {
      while (st == null || !st.hasMoreTokens()) {
        st = new StringTokenizer(br.readLine());
      }
