    static long expo(long base, long exp) {
        long t = 1L;
        long expCopy = exp;
        while (expCopy > 0) {
            if (expCopy % 2 != 0)
                t = (t * base);

            base = (base * base);
            expCopy /= 2;
        }
        return t;
    }

