		int[] a = new int[n];
		int[] b = new int[n];
		int[] c = new int[n - 1];
		int answer = 0;

		Map<Integer, Integer> m = new HashMap<>();
		a[0] = sc.nextInt();

		for (int i = 1; i < n; i++) {
			a[i] = sc.nextInt();
			m.put(a[i - 1], a[i]);
		}
		for (int i = n - 1; i >= 0; i--) {
			b[i] = sc.nextInt();
			answer += b[i];
		}

		for (int i = n - 2; i >= 0; i--) {
			c[i] = sc.nextInt();
			if (m.containsKey(i + 2)) {
				if (m.get(i + 2) == i + 1) {
					answer -= c[i];
				}
			}
		}

		System.out.println(answer);
	}
}

