		Scanner sc = new Scanner(System.in);
		String S = sc.nextLine();
		String[] spl = S.split(" ");
		int N = Integer.parseInt(spl[1]);
		int M = Integer.parseInt(spl[0]);
		String Si = "";
		int[] R = new int[M];
		int[] L = new int[M];
		for(int i = M - 1;i >= 0;i--){
			Si = sc.nextLine();
			String[] Sispl = Si.split(" ");
			R[i] = Integer.parseInt(Sispl[1]);
			L[i] = Integer.parseInt(Sispl[0]);
			Si = "";
		}
		sc.close();
		int Lmax = 1;
		int Rmin = N;
		int cnt = 0;
		for(int j = M - 1;j >= 0;j--){
			Lmax = Math.max(L[j], Lmax);
			Rmin = Math.min(R[j], Rmin);
		}
		for(int k = N;k >= 1;k--){
			if(k >= Lmax && k <= Rmin){
				cnt++;
			}
		}
		System.out.println(cnt);
	}
}

