        char[] buf = new char[n];
        int b = skip(), p = 0;
        while (p < n) {
            if (!(isSpaceChar(b)))
                buf[p++] = (char) b;
            b = readByte();
        }
        return n == p ? buf : Arrays.copyOf(buf, p);
    }

