        String n = sc.next();
        int len = n.length();
        int a = 0; // 01010101
        int b = 0; // 10101010
        for (int i = len - 1; i >= 0; i--) {
            char c = n.charAt(i);
            if (i % 2 == 0) {
                if (c == '1') {
                    a++;
                } else {
                    b++;
                }
            } else {
                if (c == '0') {
                    a++;
                } else {
                    b++;
                }
            }
        }
        System.out.println(Math.min(a, b));
    }
}

