import java.util.ArrayList;
import java.util.List;
import java.util.Scanner;

public class Main {

	public static void main(String[] args) {

		Scanner scan = new Scanner(System.in);

		int x = scan.nextInt();
		int n = scan.nextInt();
		List<Integer> p = new ArrayList<>();
		for (int i = n - 1; i >= 0; i--) {
			p.add(scan.nextInt());
		}

		for (int i = 0; i < 100; i++) {
			if (!p.contains(x - i)) {
				for (int j = 0; j < p.size(); j++) {
					if (p.get(j) == x - i) {
						p.set(j, p.get(j) + i);
						break;
					}
				}
			} else if (!p.contains(x + i)) {
				for (int j = p.size() - 1; j >= 0; j--) {
					if (p.get(j) == x + i) {
						p.set(j, p.get(j) - i);
						break;
					}
				}
			}
			if (p.contains(x - i) || p.contains(x + i)) {
				System.out.println(x - i);
				break;
			}
		}
	}
}

class Main
{
	static int count = 0;
	public static void main( String[] args )
	{
		java.util.Scanner sc = new java.util.Scanner( System.in );
		int n = sc.nextInt();
		int[] data = new int[n];
		for( int i = 0 ; i < n ; i++ )
			data[i] = sc.nextInt();
		for( int i = 0 ; i < n ; i++ )
			System.out.printf( "%d " ,data[i] );
		System.out.println();
		System.out.println( count );
		data = bubbleSort( data, n );
		for( int i = n-2 ; i > 0 ; i-- )
			System.out.printf( "%d " ,data[i] );
		System.out.println( data[0] );
	}
	static int[] bubbleSort( int[] data, int n )
	{
		boolean flag = true;
		int work;
		for( int i = n-1 ; i > 0 ; i-- )
		{
			flag = false;
			for( int j = i-1 ; j >= 0 ; j-- )
			{
				if( data[j] < data[j+1] ){
					work = data[j];
					data[j] = data[j+1];
					data[j+1] = work;
					flag = true;
					count++;
				}
			}
		}
		return data;
	}
}

