import java.io.*;
import java.util.*;
public class Main {

	/**
	 * @param args
	 */
	public static void main(String[] args) {
		BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
		PrintWriter writer = new PrintWriter(System.out);
		int student_num = Integer.parseInt(reader.readLine());
		while(student_num != 0){
			ArrayList<Integer> score_list = new ArrayList<Integer>();
			for(int i = 0; i < student_num; i++){
				score_list.add(Integer.parseInt(reader.readLine()));
			}
			Integer total = 0;
			for(int i = 0; i < student_num; i++){
				total += score_list.get(i);
			}
			double m = (double)total / student_num;
			double dev = 0;
			for(int i = 0; i < student_num; i++){
				dev += Math.pow(score_list.get(i) - m, 2);
			}
			double standard_dev = Math.sqrt(dev / student_num);
			writer.println(String.format("%.8f", standard_dev));
			student_num = Integer.parseInt(reader.readLine());
		}

	}

}

