import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        try (Scanner in = new Scanner(System.in)) {
            int N = in.nextInt();
            int X = in.nextInt();
            int[] L = new int[N];
            for (int i = N - 1; i >= 0; i--) {
                L[i] = in.nextInt();
            }

            int[] D = new int[N + 1];
            D[0] = 0;
            for (int i = 1; i <= N; i++) {
                D[i] = D[i - 1] + L[i - 1];
            }

            int count = 0;
            for (int i = N; i >= 0; i--) {
                if (D[i] <= X) {
                    count++;
                    X -= D[i];
                }
            }

            System.out.println(count);
        }
    }
}

