    class UnionFind {
        int[] parent;

        UnionFind(int n) {
            parent = new int[n];
            Arrays.fill(parent, -1);
        }

        int find(int x) {
            if (parent[x] < 0) {
                return x;
            } else {
                parent[x] = find(parent[x]);
                return parent[x];
            }
        }

        void unite(int x, int y) {
            int rootX = find(x);
            int rootY = find(y);
            if (rootX == rootY) {
                return;
            }

            if (parent[rootX] > parent[rootY]) {
                int temp = rootX;
                rootX = rootY;
                rootY = temp;
            }
            parent[rootX] += parent[rootY];
            parent[rootY] = rootX;
        }

