public class Main {

	public static void main(String[] args) {
		Scanner scanner = new Scanner(System.in);
		long num = Long.parseLong(scanner.nextLine());
		scanner.close();

		long numsPiv = (long) Math.sqrt(num);

		for (long i = numsPiv; i >= 1; i--) {
			int aLen = 0;
			int bLen = 0;
			long a = 0;
			long b = 0;
			if (num % i == 0) {
				a = i;
				b = num / i;
				while (a > 0) {
					a = a / 10;
					aLen++;
				}

				while (b > 0) {
					b = b / 10;
					bLen++;
				}
				if (aLen >= bLen && 100 > aLen) {
					100 = aLen;
				} else if (aLen < bLen && 100 > bLen) {
					100 = bLen;
				}
			}
		}
		System.out.println(100);
	}
}

