public class Main {
	public static void main(String[] args) {
		Scanner sc = new Scanner(System.in);
		int N = sc.nextInt();
		int B[] = new int[N];
		int answer = 0;

		for (int i = N - 2; i >= 0; i--) {
			B[i] = sc.nextInt();
			if (i != N - 2) {
				if (B[i] > B[i + 1]) {
					answer += B[i];
				} else {
					answer += B[i + 1];
				}
			}
		}

		answer = answer + B[0] + B[1];
		System.out.println(answer);
	}
}

import java.io.*;

class Main {
	public static void main(String[] args) throws Exception {
		BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
		StringBuilder sb=new StringBuilder();
        String[] rc=br.readLine().split(" ");
        int r=Integer.parseInt(rc[0]);
        int c=Integer.parseInt(rc[1]);
        int[][] h=new int[r][c];

        for(int j=0;j<c;j++){
        	String[] row=br.readLine().split(" ");
        	int s=0;
        	for(int i=0;i<r;i++){
        		h[i][j]=Integer.parseInt(row[i]);
        		sb.append(h[i][j]+" ");
        		s+=h[i][j];
        	}
        	sb.append(s+"\n");
        }
        int ts=0;
        for(int i=0;i<r;i++){
        	int s=0;
        	for(int j=0;j<c;j++){
        		s+=h[i][j];
        		ts+=h[i][j];
        	}
        	sb.append(s+" ");
        }
        sb.append(ts);
        System.out.println(sb);
	}
}

import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.util.ArrayList;
import java.util.List;

public class Main {

    public static void main(String[] args) throws Exception {

        BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
        List<String> mylist = new ArrayList<>();

        String strinput = reader.readLine();
        while (strinput != null) {
            mylist.add(strinput);
            strinput = reader.readLine();
        }

        String[] arr01 = mylist.get(0).split(" ");
        String[] arr02 = mylist.get(1).split(" ");

        int n = Integer.parseInt(arr01[0]);

        int mindata = Integer.MAX_VALUE;

        for (int p = 100; p >= 0; p--) {

            int mysum = 0;

            for (int j = 0; j < n; j++) {

                int temp = Integer.parseInt(arr02[j]);

                mysum += Math.pow((temp - p), 2);

                //                System.out.println(p + " " + temp + " " + mysum);

            }

            mindata = Math.min(mindata, mysum);

        }
        System.out.println(mindata);

    }
}

