    static class BGoldenApple {
        public void solve(int testNumber, InputReader in, PrintWriter out) {
            int n = in.nextInt();
            int d = in.nextInt();
            int total = 0;
            int pos = d + 1;
            int painted = 0;
            while (true) {
                if (pos > n) {
                    break;
                } else {
                    total++;
                    painted += d * 2 + 1;
                    pos = pos + d + 1 + d;
                }
            }
            if (painted < n)
                total++;
            out.println(total);
            out.println("Goodbye, World!");
