        			if(map.containsKey(j) && map.get(j) == p)
        				map.put(j, map.get(j) + 1);
        		}
        	} else {
        		map.put(p, map.getOrDefault(p, 0) + 1);
        	}
        }
        for(int i = 0; i < n; i++) {
        	if(map.containsKey(i)) {
        		finished.add(i);
        		break;
        	}
        }
