class MyStrategy implements Strategy {
    @Override
    public void solve(PrintWriter out, FastScanner sc) {
        long N = sc.nextLong();
        char[] alf = {'a', 'b', 'c', 'd', 'e', 'f', 'g', 'h', 'i', 'j', 'k', 'l', 'm', 'n', 'o', 'p', 'q', 'r', 's', 't', 'u', 'v', 'w', 'x', 'y', 'z'};
        StringBuilder sb = new StringBuilder();
        long a = N;
        int b = 0;
        while (a >= 26) {
            b = (int)(a % 26);
            a /= 26;
            if (b == 0) {
                a -= 1;
                sb.insert(0, 'z');
                if (a > 0) {
                    char s = alf[(int)(a-1)];
                    sb.insert(0, s);
                }
            } else {
                char s = alf[b-1];
                sb.insert(0, s);
                if (a > 0) {
                    a -= 1;
                    sb.insert(0, 'z');
                }
            }
        }
        if (a > 0) {
            char s = alf[(int)(a-1)];
            sb.insert(0, s);
        }
        out.println(sb.toString());
    }
}

