import java.util.Scanner;

public class Main {

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        String S = sc.next();
        System.out.println( solve(S) );
    }

    private static String solve(String S) {
        String s = reverse(S);
        String t1 = reverse("dream");
        String t2 = reverse("dreamer");
        String t3 = reverse("erase");
        String t4 = reverse("eraser");
        int i = s.length();

        do {
            i = nextIndexOf(s, i, t1, t2, t3, t4);
            if( i == -1 ) return "NO";
        } while( i < s.length() );
        return "YES";
    }

    private static String reverse(String s) {
        StringBuilder rev = new StringBuilder();
        for (int i = s.length() - 1; i >= 0; i--) {
            rev.append(s.charAt(i));
        }
        return rev.toString();
    }

    private static int nextIndexOf(String s, int i, String... ts) {
        for (int j = ts.length - 1; j >= 0; j--) {
            if( s.startsWith(ts[j], i) ) {
                return i + ts[j].length();
            }
        }
        return -1;
    }
}

