public class Main {

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);

        double sum = 100000;

        double n = sc.nextDouble();

        System.out.println((int)solve(sum, n));
    }

    public static double solve(double a, double b) {
        if (a == 0) {
            return b;
        }

        for (int i = 0; i < b; i++) {
            a = a * 1.05;

            if ((a % 1000) != 0) {
                BigDecimal bd = new BigDecimal(a / 1000);
                a = (bd.setScale(0, BigDecimal.ROUND_UP).doubleValue()) * 1000;
            }
        }
        return a;
    }
}

