import java.util.Scanner;

public class Main {
	void run() {
		Scanner sc = new Scanner(System.in);
		int b = sc.nextInt();
		int a = sc.nextInt();
		int ans = gcd(a, b);
		sc.close();
		System.out.println(ans);
	}
	int gcd(int a, int b) {
		if(b < a) {
			int c = b;
			b = a;
			a = c;
		}
		if(a == 0) return b;
		else return gcd(a%b, b);
	}

	void debug(Object... o) {
		System.out.println(Arrays.deepToString(o));
	}

	public static void main(String[] args) {
		new Main().run();
	}
}

