import java.io.*;
import java.util.stream.*;

public class Main {

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));

        Stream.generate(() -> {
            int n;
            if ((n = Integer.parseInt(br.readLine())) == 0)
                return null;
            String[] pointsStr = br.readLine().split(" ");
            int[] points = new int[n];
            for (int i = 0; i < n; i++) {
                points[i] = Integer.parseInt(pointsStr[i]);
            }
            int sum = 0;
            for (int point : points) {
                sum += point;
            }
            double mean = (new Double(sum)) / n;
            double disp = 0;
            for (int point : points) {
                disp += (point - mean) * (point - mean);
            }
            disp /= n;
            return Math.sqrt(disp);
        }).forEach(Objects::requireNonNull).forEach(System.out::printf);
    }
}

