			StringBuilder a= res(n/26-1);
			ans.append(a);
			ans.append(res(1));
		}else{
			StringBuilder a= res(n/26);
			ans.append(a);
			StringBuilder b= res(n%26);
			ans.append(b);
		}
		return ans;
	}

}

