class Main{

  	static int solve(int n, int k, int[] arr){
    	int[][] dp = new int[n][k+1];
      	dp[0][0] = 0;
        dp[1][0] = Math.abs(arr[0] - arr[1]);

      	for(int i = 2; i < n; i++){
        	dp[i][0] = dp[i-1][0] + Math.abs(arr[i-1] - arr[i]);
          	for(int j = 1; j <= k; j++){
            	if(i - j < 0)
                      break;

              	dp[i][j] = Math.min(dp[i-1][j], dp[i-j][j-1] + Math.abs(arr[i] - arr[i-j]));
            }
        }

      	return dp[n-1][k];
    }

	public static void main(String[] args){
    	Scanner scanner = new Scanner(System.in);
