		Scanner sc = new Scanner(System.in);

		// 整数の入力
		int n = sc.nextInt();

		int num = 0;
		int keta = 0;

		int n2 = n;

		for(int i = 0; n2 > 0; i++) {
			keta++;
			n2 /= 10;
		}

		for(int i = keta; i > 0; i--) {
			if(keta % 2 == 1) {
				if(keta == i) {
					num = n + 1 - (int)Math.pow(10, i-1);
				} else {
					num += (int)Math.pow(10, i-1)*9;
				}
			}
			keta--;
		}

		System.out.println(num);

        sc.close();
	}
}

