import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int X = sc.nextInt();
        int prime = X;
        int mid = prime / 2;
        boolean flag = false;
        do {
            for (int i = 2; i <= mid; ++i) {
                if (prime % i == 0) {
                    flag = true;
                    break;
                }
            }
            if (!flag) {
                break;
            } else {
                flag = false;
                prime++;
                mid = prime / 2;
            }
        } while (true);
        System.out.println(prime);
    }
}

