public class Main {
	public static void main(String[] args) {
		Scanner sc = new Scanner(System.in);
		for (int i = 0; sc.hasNext(); i++) {
			int a = sc.nextInt();
			int b = sc.nextInt();
			System.out.println(GCD(a, b) + " " + (long) a * b / GCD(a, b));
			if (i >= 1000) {
				break;
			}
		}
		sc.close();
	}

	public static int GCD(int x, int y) {
		int tmp;
		do {
			tmp = x % y;
			x = y;
			y = tmp;
		} while ((tmp = x % y) != 0);
		return y;
	}
}

import java.io.BufferedReader;
