				numArrays.add(i);
			} else {
				while (x != 0) {
					if (x % 10 == 3) {
						numArrays.add(i);
						break;
					}
					x /= 10;
				}
			}
		}
		String out = "";
		for (int i = numArrays.size() - 1; i >= 0; i--) {
			out += " " + numArrays.get(i);
		}
		System.out.println(out);
	}

}

