      //ユークリッドの互除法利用
      //Bが大きいときの最大公約数を求める
      if(B>A){
        	while(a!=0){
      			too = (b%a);
      			a = too;
      			b = a;
          }
        //最小公倍数を求める
       	System.out.println((A*B)/a); 
      }

      //Aが大きいときの最大公約数を求める
      else if(A>B){
          	while(b!=0){
        		too = (a%b);
        		b = too;
        		a = b;
        }
        //最小公倍数を求める
       	System.out.println((A*B)/b); 
      }
    }
}

