    int max = Math.max(X,Y);

    int last_price = 0;
    if(X>=Y){
      last_price = A;
    }else{
      last_price = B;
    }

    int last = max-common;
    int extra = 0;
    if(last_price>=C*2){
       extra = C*2*last;
      }else{
       extra = last_price*last;
      }

    int charge = set_AB*common+extra;
    System.out.println(charge);
    if(charge>=C*2){
      System.out.println(charge);
    }else{
      System.out.println(charge);
    }
  }
}

