    public void solve() {
        int n = in.nextInt(), k = in.nextInt();
        double res = 0;
        for (int i = 1; i <= n; i++) {
            int cnt = 1;
            int cur = i;
            while (cur < k) {
                cnt++;
                cur *= 2;
            }
            res += 1.0 / ((1L << (cnt - 1)) * n);
            res = res + res;
        }
        System.out.println(res);
    }

