class Solver {
    public void solve(long N, long K, String S) {
        int target = (int) (K - 1);
        for (int i = N - 1; i >= 0; i--) {
            if (i == target) {
                char n = (char) (S.charAt(target) - ('A' - 'a'));
                System.out.print(n);
                continue;
            }
            System.out.print(S.charAt(i));
        }
        System.out.println();
    }
}

