import javax.swing.text.StringContent;
import java.util.*;

public class Main {

    /* チェックリスト
     * 結果はintの範囲を超えていませんか？(必要な時以外はlongを使いましょう)
     * TLEしそうな処理はありませんか？
     */
    public static void main(String args[]){
        Scanner sc = new Scanner(System.in);
        int n = Integer.parseInt(sc.nextLine());
        String[] as = sc.nextLine().split(" ");
        String[] bs = sc.nextLine().split(" ");
        String[] cs = sc.nextLine().split(" ");
        List<Integer> al = new ArrayList<Integer>();
        List<Integer> bl = new ArrayList<Integer>();
        List<Integer> cl = new ArrayList<Integer>();
        for(String a : as){
            al.add(Integer.parseInt(a));
        }
        for(String b : bs){
            bl.add(Integer.parseInt(b));
        }
        for(String c : cs){
            cl.add(Integer.parseInt(c));
        }
        long r = 0;
        long prev = -2;
        long goodMood = 0;
        for(int i = al.size() - 1; i >= 0; i--){
            long rep = bl.get(i);
            r += rep;
            if(prev + 1 == i){
                r += goodMood;
            }
            prev = i;
            if(i > 0){
                goodMood = cl.get(i-1);
            }else{
                goodMood = 0;
            }
        }
        System.out.println(r);
    }
}

import java.io.BufferedReader;
import java.io.InputStreamReader;

class Queue {

	private String[] names;
	private int[] times;
	private int head;
	private int tail;
	public Queue(int size) {
		names = new String[size + 1];
		times = new int[size + 1];
	}

	public void enqueue(String name, int time) {
		names[tail] = name;
		times[tail] = time;
		if (tail++ == names.length - 1) {
			tail = 0;
		}
	}

	public int dequeue() {
		if (head == names.length - 1) {
			head = 0;
			return names.length - 1;
		}
		return head++;
	}

	public boolean isEmpty() {
		return head == tail;
	}

	public String getName(int index) {
		return names[index];
	}

	public int getTime(int index) {
		return times[index];
	}
}

public class Main {

	public static void main(String[] args) throws Exception {
		BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
		String[] strs = br.readLine().split(" ");
		int n = Integer.parseInt(strs[0]);
		int q = Integer.parseInt(strs[1]);
		Queue queue = new Queue(n);
		StringBuilder sb = new StringBuilder();
		int sumTime = 0;
		for (int i = 0; i < n; i++) {
			strs = br.readLine().split(" ");
			int time = Integer.parseInt(strs[1]);
			if (time <= q) {
				sumTime += time;
				sb.append(strs[0] + " " + sumTime + "\n");
			} else {
				sumTime += q;
				queue.enqueue(strs[0], time - q);
				for (int j = 0; j < i; j++) {
					strs = br.readLine().split(" ");
					time = Integer.parseInt(strs[1]);
					if (time <= q) {
						sumTime += time;
						sb.append(strs[0] + " " + sumTime + "\n");
					} else {
						sumTime += q;
						queue.enqueue(strs[0], time - q);
					}
				}
			}
		}
		while (!queue.isEmpty()) {
			int entryIdx = queue.dequeue();
			String name = queue.getName(entryIdx);
			int time = queue.getTime(entryIdx);
			if (time <= q) {
				sumTime += time;
				sb.append(name + " " + sumTime + "\n");
			} else {
				sumTime += 	q;
				queue.enqueue(name, time - q);
			}
		}
		System.out.print(sb.toString());
	}
}

import java.io.OutputStream;
