import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);

        long A = sc.nextLong();
        int B = sc.nextInt();
        int C = sc.nextInt();
        long D = sc.nextLong();

        System.out.println(solve(A, B, C, D));

        sc.close();
    }

    static long solve(long A, int B, int C, long D) {
        return D - A + 1 - computeMultipleNum(A, D, C) - computeMultipleNum(A, D, B)
                + computeMultipleNum(A, D, lcm(B, C));
    }

    static long lcm(long x, int y) {
        return (long) x * y / gcd(x, y);
    }

    static int gcd(long x, int y) {
        return (y == 0) ? (int) x : gcd((int) y, (int) (x % y));
    }

    static long computeMultipleNum(long A, long B, long factor) {
        long min = (A + factor - 1) / factor;
        long max = B / factor;

        return max - min + 1;
    }
}

