class Main {
    public static void main(String[] args) {
        Scanner stdIn = new Scanner(System.in);
        int n = stdIn.nextInt();
        int[] w = new int[n];
        int s1 = 0;
        int s2 = 0;
        int sub;
        int min = 10000000;
        for (int i = n - 1; i >= 0; i--) {
            w[i] = stdIn.nextInt();
        }
        for(int i = 0; i < n; i++) {
            for(int j = n - 1; j >= 0; j--) {
                if(j <= i) {
                    s1 += w[j];
                } else {
                    s2 += w[j];
                }
            }
            sub = Math.abs(s2 - s1);
            if(sub < min) {
                min = sub;
            }
            s1 = 0;
            s2 = 0;
        }
        System.out.println(min);
    }
}

import java.util.Scanner;
public class Main {

	public static void main(String[] args) {
		Scanner sc = new Scanner(System.in);
		for( ; true ; ) {
			int n;
			n = sc.nextInt();
			if(n==0) {
				break;
			}
			double[] num;
			double sum = 0;
			num = new double[n];
			for(int i = n-1 ; i >= 0 ; i--) {
				num[i] = sc.nextInt();
				sum += num[i];
			}

			double ave = sum/n;
			double sum_2 = 0;
			for(int i = n-1 ; i >= 0 ; i--) {
				sum_2 += (num[i]-ave)*(num[i]-ave);
			}
			double bunsan = sum_2/n;
			double ans = Math.sqrt(bunsan);
			System.out.printf("%f\n",ans);
		}
		sc.close();
	}
}

