        if (H == 1) {
            return 1;
        }
        return getAttackOneMonster(H / 2) + 1;
    }
}

class FastScanner {
    private final InputStream in = System.in;
    private final byte[] buffer = new byte[1024];
    private int ptr = 0;
    private int buflen = 0;

    private boolean hasNextByte() {
        if (ptr < buflen) {
            return true;
        } else {
            ptr = 0;
            try {
                buflen = in.read(buffer);
            } catch (IOException e) {
                e.printStackTrace();
            }
            if (buflen <= 0) {
                return false;
            }
        }
        return true;
    }

    private int readByte() {
        if (hasNextByte()) {
            return buffer[ptr++];
        }
        else {
            return -1;
        }
    }

    private static boolean isPrintableChar(int c) {
        return 33 <= c && c <= 126;
    }

    private void skipUnprintable() {
        while (hasNextByte() && !isPrintableChar(buffer[ptr])) {
            ptr++;
        }
    }

    public boolean hasNext() {
        skipUnprintable();
        return hasNextByte();
    }

    public String next() {
        if (!hasNext()) {
            throw new NoSuchElementException();
        }
        StringBuilder sb = new StringBuilder();
        int b = readByte();
        while (isPrintableChar(b)) {
            sb.appendCodePoint(b);
            b = readByte();
        }
        return sb.toString();
    }

    public int nextInt() {
        if (!hasNext()) {
            throw new NoSuchElementException();
        }
        int n = 0;
        boolean minus = false;
        int b = readByte();
        if (b == '-') {
            minus = true;
            b = readByte();
        }
        if (b < '0' || '9' < b) {
            throw new NumberFormatException();
        }
        while (true) {
            if ('0' <= b && b <= '9') {
                n *= 10;
                n += b - '0';
            } else if (b == -1 || !isPrintableChar(b)) {
                return minus ? -n : n;
            } else {
                throw new NumberFormatException();
            }
            b = readByte();
        }
    }

    public long nextLong() {
        if (!hasNext()) {
            throw new NoSuchElementException();
        }
        long n = 0;
        boolean minus = false;
        int b = readByte();
        if (b == '-') {
            minus = true;
            b = readByte();
        }
        if (b < '0' || '9' < b) {
            throw new NumberFormatException();
        }
        while (true) {
            if ('0' <= b && b <= '9') {
                n *= 10;
                n += b - '0';
            } else if (b == -1 || !isPrintableChar(b)) {
                return minus ? -n : n;
            } else {
                throw new NumberFormatException();
            }
            b = readByte();
        }
    }
}

import java.util.*;

public class Main {
  public static void main(String[] args) {
    Main main = new Main();
    main.show();
    main.solve();
  }

  List<Deque<Integer>> a;
  int ans;
  int turn = N;
  boolean win = true;
  static final int A = 0;
  static final int B = 1;
  static final int C = 2;
  static final int N = 3;

  public Main() {
    Scanner sc = new Scanner(System.in);
    try {
      a = new ArrayList<Deque<Integer>>();
      a.add(read(sc));
      a.add(read(sc));
      a.add(read(sc));
    } finally {
      sc.close();
    }
  }

  private static Deque<Integer> read(Scanner sc) {
    Deque<Integer> ans = new ArrayDeque<Integer>();
    String s = sc.next();
    int n = s.length();
    for (int i = n - 1; i >= 0; i--) {
      if (s.charAt(i) == 'c' ) ans.addFirst(C);
      if (s.charAt(i) == 'b' ) ans.addFirst(B);
      if (s.charAt(i) == 'a' ) ans.addFirst(A);
    }
    return ans;
  }

  void solve() {
    while (!win) {
      turn = a.get(turn).pollLast();
      if (a.get(turn).size() == 0) {
        win = false;
        ans = turn;
      }
    }
  }

  void show() {
    if (ans == A) System.out.println("A");
    if (ans == B) System.out.println("B");
    if (ans == C) System.out.println("C");
  }
}

