                 - (b / lcm(d, c) - (a - 1) / lcm(d, c)));
        System.out.println(ans);
    }
    static long gcd(long m, long n) {
        long r = m % n;
        while(r > 0) {
            m = n;
            n = r;
            r = m % n;
        }
        return n;
    }
    static long lcm(long m, long n) {
        return n * m / gcd(n, m);
    }
    static long gcd(long n, long m) {
        long r = n % m;
        while(r > 0) {
            n = m;
            m = r;
            r = n % m;
        }
        return m;
    }
}

