public class Main {
	public static void main(String[] args) throws Exception {
		InputStream is = System.in;
		solve(is);
	}

	private static void solve(InputStream is) {
		try (Scanner cin = new Scanner(is)) {
			int n = cin.nextInt();
			int[] a = new int[n];
			int[] b = new int[n];

			for (int i = n - 1; i >= 0; i--) {
				a[i] = cin.nextInt();
			}
			for (int i = n - 1; i >= 0; i--) {
				b[i] = cin.nextInt();
			}

			int ans = 0;
			int candy = 0;

			for (int x = n - 1; x >= 0; x--) {
				for (int i = x; i >= 0; i--) {
					candy += a[i];
				}
				for (int i = x; i < n; i++) {
					candy += b[i];
				}
				ans = ans > candy ? ans : candy;
				candy = 0;
			}

			System.out.println(ans);
		}
	}
}

