		Iterator<Integer> itL = new ArrayList<Integer>().iterator();
		while(scan.hasNext()){
			int a = scan.nextInt();
			int b = scan.nextInt();
			int g = gcd(b, a);
			int l = lcm(a, b, g);
			itG.add(g);
			itL.add(l);
		}
		while(itG.hasNext()){
			int g = itG.next();
			int l = itL.next();
			System.out.printf("%d %d\n", l, g);
		}
	}

	public static int gcd(int a, int b){
		if(a != 0)return gcd(b, a % b);
		else return b;
	}

	public static int lcm(int a, int b, int g){
		int v = b / g;
		int l = v * a;
		return l;
	}
}

