        FastScanner fs = new FastScanner();
        int k = fs.nextInt();
        long ans = 0;
        for(int i=1; i<=k; ++i){
            for(int j=k; j>=1; --j){
                for(int h=1; h<=k; ++h){
                    ans += gcd(h,gcd(i,j));
                }
            }
        }
        System.out.println(ans);
    }
    public static int gcd(int a, int b){
        if(b == 0) return a;
        return gcd(b,a%b);
    }

