    static int f(LinkedList<Integer> q) {
        int size = q.size();
        int count = 0;
        size /= 2;
        while (size-- > 0) {
            int first = q.pollFirst();
            int second = q.pollLast();
            if (first + second >= 10) count++;
            int newValue = (first + second) % 10;
            q.addFirst(newValue);
        }
        return count;
    }
}

