    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;

public class Main {

    static final BufferedReader in = new BufferedReader(new InputStreamReader(System.in));

    public static void main(String[] args) throws IOException {

        // --- resolv ---
        int[] cur = {0, 0, 0};
        int[] mv = new int[3];
        boolean found = false;
        for(int i=0; i < Integer.MAX_VALUE; i++) {

            // --- input ---
            int val = toInt(in.readLine());
            int[][] data = new int[val][];
            for(int j=0; j < val; j++) {
                data[j] = toIntAry(in.readLine().split(" "));
            }

            for(int[] next : data) {

                for(int k=0; k < 3; k++) {
                    mv[k] = Math.abs(next[k] - cur[k]);
                }

                if(mv[0] < (mv[1] + mv[2]) || mv[0] % 2 != (mv[1] + mv[2]) % 2) {
                    System.out.println("No");
                    found = true;
                    return;
                }

                // current
                cur = next;
            }

            if(found) {
                return;
            }
        }

        System.out.println("Yes");
    }

    public static int toInt(String val) {
        return Integer.parseInt(val);
    }

    public static int[] toIntAry(String[] vals) {
        int[] vAry = new int[vals.length];
        for(int i=0; i < vals.length; i++) {
            vAry[i] = toInt(vals[i]);
        }
        return vAry;
    }
}

