public class Main {

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);

        int N = sc.nextInt();
        int Q = sc.nextInt();
        String s = sc.next();

        int[] sum = new int[N + 1];
        Arrays.fill(sum, 0);
        for (int i = N - 1; i >= 0; i--) {
            if (i + 1 < N && s.charAt(i) == 'C' && s.charAt(i + 1) == 'A')
                sum[i] = sum[i + 1] + 1;
            else
                sum[i] = sum[i + 1];
        }

        for (int i = 0; i < Q; i++) {
            int l = sc.nextInt();
            int r = sc.nextInt();

            int ans = sum[l - 1] - sum[r - 1];
            System.out.println(ans);
        }
    }
}

