		long l;
		long r;

		Scanner sc = new Scanner(System.in);

		r =  sc.nextInt();
		l =  sc.nextInt();

		long res;

		if (l >= 2018) {
			res = 0;
		} else {

			res = 2018;

			for (long i = r; i > l; i--) {

