public class Main {
	public static long gcd(long a, long b) {
		if(a < b) {
			long tmp = a;
			a = b;
			b = tmp;
		}
		long r = a;
		a = 0;
		b = r;
		while(b != 0) {
			r = a % b;
			a = b;
			b = r;
		}
		return a;
	}

	public static void main(String[] args) {
		Scanner sc = new Scanner(System.in);
		for(int i = 0; sc.hasNext(); i++) {
			int a = sc.nextInt();
			int b = sc.nextInt();

			long g = gcd(a, b);
			long l = a / g * b;
			System.out.println(g + " " + l);
			if(i % 10 == 0) {
				System.out.println("Processing...");
			}
		}
		sc.close();
	}

}

