        Scanner sc = new Scanner(System.in);
        long N = sc.nextLong();
        long min = INF;
        for (long i = Math.sqrt(N); i >= 1; i--) {
            if (N % i == 0) {
                min = Math.min(min, i + N / i - 2);
            }
        }
        for (long i = 2; i <= Math.sqrt(N); i++) {
            if (N % i == 0) {
                min = Math.min(min, i + N / i - 2);
            }
        }
        System.out.println(min);
