        int N = Integer.parseInt(sc.next());
        int[] h = new int[N];
        int max = 0;
        for(int i = 0; i < N; i++) {
            h[i] = Integer.parseInt(sc.next());
            if(max < h[i]) {
                max = h[i];
            }
        }
        int count = 0;
        do {
            if(N == 1) {
                count = h[0];
                break;
            }
            for(int i = N - 1; i > 0; i--) {
                if(h[i] == max) {
                    h[i]--;
                    if(h[i - 1] != max) {
                        count++;
                    }
                }
            }
            max--;
        } while(max > 0);
        System.out.println(count);
    }
}

