		}
	}
}

class data{
	String name;
	int time;

	data(String name, int time){
		this.name = name;
		this.time = time;
	}
}

class queue{
	ArrayList<data> Q;
	int head, tail;

	queue(){
		Q = new ArrayList<data>();
		head = tail = 0;
	}

	void enqueue(String name, int time){
		data process = new data(name, time);

		Q.add(process);
		tail ++;
	}

	data dequeue(){
		data process = Q.get(head);

		head ++;

		return process;
	}

	boolean isEmpty(){
		if(head == tail){
			return true;
		}
		else{
			return false;
		}
	}
}

