public final class Main {

    public static void main(String[] args) {
        final FastScanner fs = new FastScanner();
        final int n = fs.nextInt();
        int[] arr = new int[n + 1];
        for (int i = 0; i < n; i++) {
            arr[i] = fs.nextInt();
        }
        int[] dp = new int[n + 1];
        Arrays.fill(dp, (int) 1e9);
        dp[0] = 0;
        for (int i = 0; i < n - 1; i++) {
            dp[i + 1] = Math.min(dp[i + 1], dp[i] + Math.abs(arr[i + 1] - arr[i]));
            dp[i + 2] = Math.min(dp[i + 2], dp[i] + Math.abs(arr[i + 2] - arr[i]));
            if (i < n - 2) {
                dp[i + 3] = Math.min(dp[i + 3], dp[i] + Math.abs(arr[i + 3] - arr[i]));
            }
        }
        System.out.println(dp[n - 1]);
    }

    static final class Utils {
        public static void shuffleSort(int[] arr) {
            shuffle(arr);
            Arrays.sort(arr);
        }

        public static void shuffleSort(long[] arr) {
            shuffle(arr);
            Arrays.sort(arr);
        }

        public static void shuffle(int[] arr) {
            final Random r = new Random();
            for (int i = arr.length - 1; i > 0; i--) {
                final int j = i - r.nextInt(i);
                swap(arr, i, j);
            }
        }

        public static void shuffle(long[] arr) {
            final Random r = new Random();
            for (int i = arr.length - 1; i > 0; i--) {
                final int j = i - r.nextInt(i);
                swap(arr, i, j);
            }
        }

        public static void swap(int[] arr, int i, int j) {
            final int t = arr[i];
            arr[i] = arr[j];
            arr[j] = t;
        }

        public static void swap(long[] arr, int i, int j) {
            final long t = arr[i];
            arr[i] = arr[j];
            arr[j] = t;
        }

        private Utils() {}
    }

    static class FastScanner {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer("");
        int[] buffer = new int[100];
        int bufferIndex = 0;

        private String next() {
            while (!st.hasMoreTokens()) {
                try {
                    st = new StringTokenizer(br.readLine());
                } catch (IOException e) {
                    //noinspection CallToPrintStackTrace
                    e.printStackTrace();
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            if (bufferIndex == buffer.length) {
                bufferIndex = 0;
                try {
                    buffer = new int[buffer.length * 2];
                    String line = br.readLine();
                    String[] parts = line.split(" ");
                    for (String part : parts) {
                        buffer[bufferIndex++] = Integer.parseInt(part);
                    }
                } catch (IOException e) {
                    //noinspection CallToPrintStackTrace
                    e.printStackTrace();
                }
            }
            return buffer[bufferIndex++];
        }

        long nextLong() {
            if (bufferIndex == buffer.length) {
                bufferIndex = 0;
                try {
                    buffer = new int[buffer.length * 2];
                    String line = br.readLine();
                    String[] parts = line.split(" ");
                    for (String part : parts) {
                        buffer[bufferIndex++] = Long.parseLong(part);
                    }
                } catch (IOException e) {
                    //noinspection CallToPrintStackTrace
                    e.printStackTrace();
                }
            }
            return buffer[bufferIndex++];
        }

        int[] nextIntArray(int n) {
            final int[] a = new int[n];
            for (int i = 0; i < n; i++) { a[i] = nextInt(); }
            return a;
        }

        long[] nextLongArray(int n) {
            final long[] a = new long[n];
            for (int i = 0; i < n; i++) { a[i] = nextLong(); }
            return a;
        }
    }
}

