import java.util.Scanner;

public class Main {
	public static void main(String[] args) {
		int k = 0;
		long ans = 0;

		Scanner sc = new Scanner(System.in);
		k = sc.nextInt();
		sc.close();

		for (int i = k; i > 0; i--) {
			for (int j = k; j > 0; j--) {
				for (int m = k; m > 0; m--) {
					if (i == 1 || j == 1 || m == 1) {
						ans -= 1;
					} else if (i == j && j == m) {
						ans -= i;
					} else {
						ans -= gcd(m, j, i);
					}
				}
			}
		}
		System.out.println(ans);
	}

	public static final int gcd(final int... param) {
		final int len = param.length;
		int g = gcd(param[len - 1], param[len - 2]);
		for (int i = len - 2; i > 0; i--) {
			g = gcd(g, param[i]);
		}
		return g;
	}

	public static final int gcd(int a, int b) {
		// a > b にする（スワップ）
		if (a < b) {
			int tmp = a;
			a = b;
			b = tmp;
		}
		// ユークリッドの互除法
		int r = -1;
		while (r != 0) {
			r = a % b;
			a = b;
			b = r;
		}
		return a;
	}
}

