import java.util.*;
public class Main {

	public static void main(String[] args) {
		Queue<String> seq = new LinkedList<String>();
		String opers = "+-/*";
		ArrayList<String> arr = new ArrayList<String>();
		Scanner out = new Scanner(System.in);
		String line = out.nextLine();
		Scanner in = new Scanner(line);
		while(in.hasNext()) {
			arr.add(in.next());
		}
		for(int i = arr.size() - 1; i >= 0; i--) {
			if(opers.contains(arr.get(i))) {
				int num = Integer.valueOf(seq.poll());
				int num1 = Integer.valueOf(seq.poll());
				if(arr.get(i).equals(opers.substring(0, 1))) {
					seq.offer(String.valueOf(num1 + num));
				}
				else if(arr.get(i).equals(opers.substring(1, 2))) {
					seq.offer(String.valueOf(num1 - num));
				}
				else if(arr.get(i).equals(opers.substring(2, 3))) {
					seq.offer(String.valueOf(num1 / num));
				}
				else {
					seq.offer(String.valueOf(num1 * num));
				}
			}
			else seq.add(arr.get(i));
		}
		System.out.println(Integer.valueOf(seq.poll()));
	}

}

