        public void run(InputScanner in, PrintWriter out) {

            String[] S = in.nextStringArray(" ");
            long K = in.nextLong();

            int ans = 1;
            for (int i = 0; i < S.length; i++) {

                int num = Integer.parseInt(S[i]);

                if (num != 1) {
                    if (i + 1 > K) {
                        ans = 1;
                    } else {
                        ans = num;
                    }
                    break;
                }
            }

            out.println(ans);
        }
    }

