public class Main {
    static Scanner sc = new Scanner(System.in);
    public static void main(String args[]) {
        int n = sc.nextInt();
        int[] p = new int[n];
        for(int i = n - 1; i >= 0; i--) p[i] = sc.nextInt();
        boolean ans = false;
        boolean ok = true;
        for(int i = n - 1; i > 0; i--) {
            for(int j = i - 1; j >= 0; j--) {
                int tmp = p[i];
                p[i] = p[j];
                p[j] = tmp;
