		int M = sc.nextInt();
		int[] p = new int[M];
		String[] S = new String[M];

		for (int i = M - 1; i >= 0; i--) {
			p[i] = sc.nextInt() - 1;
			S[i] = sc.next();
		}
		sc.close();

		boolean[] ac = new boolean[N];
		Arrays.fill(ac, false);

		boolean[] b = new boolean[N];
		for(int i=M-1;i>=0;i--) {
			if(S[i].equals("AC")) {
				b[p[i]] = true;
			}
		}


		int numOfAC = 0;
		int numOfWA = 0;

		for (int i = M - 1; i >= 0; i--) {
			if (S[i].equals("AC")) {
				if (!ac[p[i]]) { //AC済みでないなら
					numOfAC++;
					ac[p[i]] = true;
				}
				//AC済みならすでにカウントされているので何もしない

			} else { // WA
				if (!ac[p[i]] && b[p[i]]) { //AC済みでないなら
					numOfWA++; //ペナルティを増やす
				}
				//AC済みならペナルティなし
			}
		}

